'use client';

import { PolymarketMarket } from '@/types/polymarket';

interface MarketsTableProps {
  markets: PolymarketMarket[];
}

export default function MarketsTable({ markets }: MarketsTableProps) {
  const formatPrice = (price: string | undefined) => {
    if (!price) return 'N/A';
    const numPrice = parseFloat(price);
    return (numPrice * 100).toFixed(2) + '%';
  };

  const formatVolume = (volume: string | undefined) => {
    if (!volume) return 'N/A';
    const numVolume = parseFloat(volume);
    if (numVolume >= 1000000) {
      return '$' + (numVolume / 1000000).toFixed(2) + 'M';
    }
    if (numVolume >= 1000) {
      return '$' + (numVolume / 1000).toFixed(2) + 'K';
    }
    return '$' + numVolume.toFixed(2);
  };

  const getStatusBadge = (market: PolymarketMarket) => {
    if (market.closed) {
      return <span className="px-2 py-1 rounded text-xs font-medium bg-gray-500 text-white">Closed</span>;
    }
    if (market.archived) {
      return <span className="px-2 py-1 rounded text-xs font-medium bg-gray-400 text-white">Archived</span>;
    }
    if (market.active) {
      return <span className="px-2 py-1 rounded text-xs font-medium bg-green-500 text-white">Active</span>;
    }
    return <span className="px-2 py-1 rounded text-xs font-medium bg-yellow-500 text-white">Pending</span>;
  };

  const getOutcomePrices = (market: PolymarketMarket) => {
    // Ensure outcomes is an array
    let outcomes: string[] = [];
    if (Array.isArray(market.outcomes)) {
      outcomes = market.outcomes;
    } else if (market.outcomes) {
      // If it's not an array but exists, try to convert it
      outcomes = [market.outcomes.toString()];
    }
    
    // If no outcomes array, try to get from tokens
    if (outcomes.length === 0 && market.tokens) {
      if (Array.isArray(market.tokens)) {
        // If tokens is an array, extract outcomes from it
        outcomes = market.tokens
          .map((token: any) => token.outcome || token.name)
          .filter((outcome: any) => outcome);
      } else if (typeof market.tokens === 'object') {
        // If tokens is an object, use the keys
        outcomes = Object.keys(market.tokens);
      }
    }
    
    if (outcomes.length === 0) return 'N/A';
    
    const prices = outcomes.map((outcome) => {
      const tokenKey = outcome.toLowerCase().replace(/\s+/g, '-');
      const token = market.tokens?.[tokenKey] || market.tokens?.[outcome];
      const price = token?.price || market.outcomePrices?.[outcome] || '0';
      return `${outcome}: ${formatPrice(price)}`;
    });
    
    return prices.join(' | ');
  };

  if (markets.length === 0) {
    return (
      <div className="text-center py-8">
        <p className="text-zinc-600 dark:text-zinc-400">No markets to display</p>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full border-collapse">
        <thead>
          <tr className="border-b border-zinc-200 dark:border-zinc-800">
            <th className="text-left py-3 px-4 font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              Market
            </th>
            <th className="text-left py-3 px-4 font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              Prices
            </th>
            <th className="text-right py-3 px-4 font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              Volume
            </th>
            <th className="text-right py-3 px-4 font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              Liquidity
            </th>
            <th className="text-center py-3 px-4 font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              Status
            </th>
            <th className="text-left py-3 px-4 font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              End Date
            </th>
            <th className="text-center py-3 px-4 font-semibold text-zinc-900 dark:text-zinc-100 text-sm">
              Link
            </th>
          </tr>
        </thead>
        <tbody>
          {markets.map((market) => (
            <tr
              key={market.id}
              className="border-b border-zinc-100 dark:border-zinc-900 hover:bg-zinc-50 dark:hover:bg-zinc-900/50 transition-colors"
            >
              <td className="py-3 px-4">
                <div className="max-w-md">
                  <div className="font-medium text-zinc-900 dark:text-zinc-100 text-sm">
                    {market.question}
                  </div>
                  {market.description && (
                    <div className="text-xs text-zinc-500 dark:text-zinc-500 mt-1 line-clamp-1">
                      {market.description}
                    </div>
                  )}
                </div>
              </td>
              <td className="py-3 px-4">
                <div className="text-sm text-zinc-700 dark:text-zinc-300 max-w-xs">
                  {getOutcomePrices(market)}
                </div>
              </td>
              <td className="py-3 px-4 text-right">
                <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                  {formatVolume(market.volume)}
                </span>
              </td>
              <td className="py-3 px-4 text-right">
                <span className="text-sm font-medium text-zinc-900 dark:text-zinc-100">
                  {formatVolume(market.liquidity)}
                </span>
              </td>
              <td className="py-3 px-4 text-center">
                {getStatusBadge(market)}
              </td>
              <td className="py-3 px-4">
                <span className="text-sm text-zinc-600 dark:text-zinc-400">
                  {market.endDateISO
                    ? new Date(market.endDateISO).toLocaleDateString()
                    : 'N/A'}
                </span>
              </td>
              <td className="py-3 px-4 text-center">
                {market.slug ? (
                  <a
                    href={`https://polymarket.com/event/${market.slug}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-blue-600 dark:text-blue-400 hover:underline text-sm font-medium"
                  >
                    View →
                  </a>
                ) : (
                  <span className="text-zinc-400 dark:text-zinc-600 text-sm">—</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}


