'use client';

import { PolymarketMarket } from '@/types/polymarket';

interface MarketCardProps {
  market: PolymarketMarket;
}

export default function MarketCard({ market }: MarketCardProps) {
  const formatPrice = (price: string | undefined) => {
    if (!price) return 'N/A';
    const numPrice = parseFloat(price);
    return (numPrice * 100).toFixed(2) + '%';
  };

  const formatVolume = (volume: string | undefined) => {
    if (!volume) return 'N/A';
    const numVolume = parseFloat(volume);
    if (numVolume >= 1000000) {
      return '$' + (numVolume / 1000000).toFixed(2) + 'M';
    }
    if (numVolume >= 1000) {
      return '$' + (numVolume / 1000).toFixed(2) + 'K';
    }
    return '$' + numVolume.toFixed(2);
  };

  const getStatusColor = () => {
    if (market.closed) return 'bg-gray-500';
    if (market.archived) return 'bg-gray-400';
    if (market.active) return 'bg-green-500';
    return 'bg-yellow-500';
  };

  const outcomes = market.outcomes || [];
  const tokens = market.tokens || {};

  return (
    <div className="bg-white dark:bg-zinc-900 rounded-lg border border-zinc-200 dark:border-zinc-800 p-6 hover:shadow-lg transition-shadow">
      <div className="flex items-start justify-between mb-4">
        <div className="flex-1">
          <h3 className="text-lg font-semibold text-zinc-900 dark:text-zinc-100 mb-2">
            {market.question}
          </h3>
          {market.description && (
            <p className="text-sm text-zinc-600 dark:text-zinc-400 line-clamp-2">
              {market.description}
            </p>
          )}
        </div>
        <span
          className={`ml-4 px-2 py-1 rounded text-xs font-medium text-white ${getStatusColor()}`}
        >
          {market.closed ? 'Closed' : market.archived ? 'Archived' : market.active ? 'Active' : 'Pending'}
        </span>
      </div>

      {outcomes.length > 0 && (
        <div className="space-y-2 mb-4">
          {outcomes.map((outcome, index) => {
            const tokenKey = outcome.toLowerCase().replace(/\s+/g, '-');
            const token = tokens[tokenKey] || tokens[outcome] || {};
            const price = token.price || market.outcomePrices?.[outcome] || '0';
            
            return (
              <div key={index} className="flex items-center justify-between">
                <span className="text-sm font-medium text-zinc-700 dark:text-zinc-300">
                  {outcome}
                </span>
                <span className="text-sm font-semibold text-zinc-900 dark:text-zinc-100">
                  {formatPrice(price)}
                </span>
              </div>
            );
          })}
        </div>
      )}

      <div className="flex items-center justify-between text-xs text-zinc-500 dark:text-zinc-500 pt-4 border-t border-zinc-200 dark:border-zinc-800">
        <div className="flex gap-4">
          {market.volume && (
            <span>
              Volume: <span className="font-medium">{formatVolume(market.volume)}</span>
            </span>
          )}
          {market.liquidity && (
            <span>
              Liquidity: <span className="font-medium">{formatVolume(market.liquidity)}</span>
            </span>
          )}
        </div>
        {market.endDateISO && (
          <span>
            Ends: {new Date(market.endDateISO).toLocaleDateString()}
          </span>
        )}
      </div>

      {market.slug && (
        <a
          href={`https://polymarket.com/event/${market.slug}`}
          target="_blank"
          rel="noopener noreferrer"
          className="mt-4 block text-center text-sm font-medium text-blue-600 dark:text-blue-400 hover:underline"
        >
          View on Polymarket →
        </a>
      )}
    </div>
  );
}



